-- 0094 — Login passwords (EPCs + the CC team).
--
-- Rule: once CC sets a password for an account, logging in needs mobile +
-- password; an account with no password yet logs in with the mobile only (as
-- before) — new EPCs sign up and onboard that way, and CC sets their password
-- after approval.
--
-- Passwords are stored ONLY as bcrypt hashes in login_credentials, which has
-- RLS on and NO policies: no browser (EPC or admin) can read or write it. All
-- access is through SECURITY DEFINER functions. Passwords are GENERATED by the
-- portal (strong: 12+ chars, upper/lower/digit/symbol — enforced here too):
--   set_login_password(id, pw)   MAIN admin only (EPC and CC-team accounts);
--                                the portal saves it only after the password
--                                email to the account was sent
--   login_password_status(ids)   admins: when each account's password was set
--   verify_login_password(id,pw) service role only (the `auth` edge function):
--                                'none' | 'required' | 'ok' | 'bad' | 'locked'
-- 5 wrong passwords lock the account for 15 minutes.

create extension if not exists pgcrypto with schema extensions;

create table if not exists login_credentials (
  business_id   uuid primary key references epc_business(id) on delete cascade,
  password_hash text not null,
  failed_count  int not null default 0,
  locked_until  timestamptz,
  updated_at    timestamptz not null default now(),
  updated_by    uuid
);
alter table login_credentials enable row level security;
revoke all on login_credentials from anon, authenticated;

create or replace function set_login_password(p_business_id uuid, p_password text)
returns timestamptz
language plpgsql security definer set search_path = public, extensions as $$
declare
  caller_type text := nullif(auth.jwt() ->> 'business_type', '');
  caller_role text := coalesce(auth.jwt() ->> 'hierarchy_role', '');
  target_type text;
  v_at timestamptz := now();
begin
  if caller_type is distinct from 'admin' then
    raise exception 'admin_only' using errcode = '42501';
  end if;
  if caller_role not in ('MAIN_ADMIN', '') then
    raise exception 'main_admin_only' using errcode = '42501';
  end if;
  select business_type into target_type from epc_business where id = p_business_id;
  if not found then raise exception 'account_not_found'; end if;
  -- Strong only (the portal generates them): 12+ chars with upper, lower, digit, symbol.
  if p_password is null or length(p_password) < 12
     or p_password !~ '[A-Z]' or p_password !~ '[a-z]' or p_password !~ '[0-9]' or p_password !~ '[^A-Za-z0-9]' then
    raise exception 'password_not_strong';
  end if;
  insert into login_credentials (business_id, password_hash, failed_count, locked_until, updated_at, updated_by)
  values (p_business_id, crypt(p_password, gen_salt('bf', 10)), 0, null, v_at, nullif(auth.jwt() ->> 'business_id', '')::uuid)
  on conflict (business_id) do update
    set password_hash = excluded.password_hash, failed_count = 0, locked_until = null,
        updated_at = excluded.updated_at, updated_by = excluded.updated_by;
  return v_at;
end $$;

create or replace function login_password_status(p_business_ids uuid[])
returns table (business_id uuid, updated_at timestamptz)
language plpgsql security definer set search_path = public as $$
begin
  if nullif(auth.jwt() ->> 'business_type', '') is distinct from 'admin' then
    raise exception 'admin_only' using errcode = '42501';
  end if;
  return query select c.business_id, c.updated_at from login_credentials c where c.business_id = any(p_business_ids);
end $$;

create or replace function verify_login_password(p_business_id uuid, p_password text)
returns text
language plpgsql security definer set search_path = public, extensions as $$
declare
  c login_credentials%rowtype;
begin
  select * into c from login_credentials where business_id = p_business_id for update;
  if not found then return 'none'; end if;
  if c.locked_until is not null and c.locked_until > now() then return 'locked'; end if;
  if p_password is null or p_password = '' then return 'required'; end if;
  if crypt(p_password, c.password_hash) = c.password_hash then
    update login_credentials set failed_count = 0, locked_until = null where business_id = p_business_id;
    return 'ok';
  end if;
  update login_credentials
    set failed_count = case when c.failed_count + 1 >= 5 then 0 else c.failed_count + 1 end,
        locked_until = case when c.failed_count + 1 >= 5 then now() + interval '15 minutes' else null end
    where business_id = p_business_id;
  return 'bad';
end $$;

revoke execute on function set_login_password(uuid, text) from public, anon;
revoke execute on function login_password_status(uuid[]) from public, anon;
revoke execute on function verify_login_password(uuid, text) from public, anon, authenticated;
grant execute on function set_login_password(uuid, text) to authenticated;
grant execute on function login_password_status(uuid[]) to authenticated;
grant execute on function verify_login_password(uuid, text) to service_role;
